"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97476"],{44516(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.precedencia_fase.sucessora_codigo_formato_invalido","status":422,"titulo":"C\xf3digo da fase sucessora em formato inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.precedencia_fase.sucessora_codigo_formato_invalido","requisitos":[],"oQueAconteceu":["O campo `sucessoraCodigo` do cadastro de uma preced\xeancia (`POST /api/configuracao/admin/precedencias-fase`) n\xe3o respeita o formato do c\xf3digo de fase: letra mai\xfascula inicial, seguida de letras mai\xfasculas ou d\xedgitos e sublinhados isolados, com no m\xe1ximo 60 caracteres. O c\xf3digo \xe9 conferido como recebido. Esta confer\xeancia \xe9 s\xf3 de formato; um c\xf3digo bem formado ainda precisa ser um dos catorze do vocabul\xe1rio de fases (ver [c\xf3digo da fase sucessora fora do conjunto can\xf4nico](/erros/uniplus.configuracao.precedencia_fase.sucessora_fora_do_conjunto_canonico)).","A recusa vem na lista `errors` da resposta, com `field` igual a `sucessoraCodigo`. Se o outro c\xf3digo tamb\xe9m tiver problema, a recusa dele vem na mesma resposta, e nada \xe9 gravado."],"comoResolver":["Use o c\xf3digo no formato do vocabul\xe1rio, por exemplo `INSCRICAO` ou `RESULTADO_FINAL`. Os c\xf3digos v\xe1lidos v\xeam de `GET /api/configuracao/vocabularios/fases-canonicas`."],"ondeAparece":["Cadastro de uma preced\xeancia entre fases"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Precedencia fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);